) AS (
  VALUES 
    (116::BIGINT, 'Profe bastante simpatico y buena nota, no pierde tiempo en clases, deja mucho trabajo en grupo y tareas pero es fácil de pasar si se hace todo y califica bastante bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2026-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'a63ccbf5d77664fb4faf495cb1aa290226877c339c8da120a254b26ad5b6e3dc'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Él como persona es un amor. El curso se pasa muy fácil. Sin embargo uno tiene que hacer muchos trabajos grupales tediosos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ce4679f55640f27264cba2db0fdf30246d88ba1a22eea599a99839d473e9d79c'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor, en modalidad virtual es muy fácil. Sin embargo, hay que prestar atención a las clases ya que usualmente las tareas las hace ahí mismo o hace preguntas. Pero se pasa muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ce4d7055fd74c93089e4bedceeb1ff8d04a0e54b6b3be14c597e096839e95b85'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e1d11894ad40e22e1fe42ef4c13ff3ac656c0821faa643f52735874d446fff59'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'No le mencionen de la ex esposa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '08ff9879b26a720a8eafb7dd2b834e6c33636bc85479dab1ed16e52cac0d141d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Clases entretenidas y trabajos casi todas las clases, pero bastantes simples, deja varios trabajos pero se hacen en menos de una hora.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '9b3f623a48a0858f4d8ec101a60a5d1e6dcf362f07517561262067e4d01d1d3d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor se esmera porque todos entiendan la clase, normalmente sus clases usan la metodologia de clase invertida, y la mayoria de sus trabajos son grupales, simplemente con que tengan un buen grupo de trabajo todo sale rapido y facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'cbd6d11ae3fc6c8a872501d0f7b1d488faaaf4ddffbac9a4bfa610122a7c631d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El profe es excelente, sus clases son muy agradables, como persona es increíble, muy comprensivo, transmite tranquilidad y hace el curso muy sencillo y ameno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'ba728409264603a6cfeaac6c21339c136d83b15e0b8134262657844049e390d4'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Una teja de profe, todos los trabajos se hacen fácil y rápido. El profe se preocupa por los estudiantes y si hablas con el podes resolver la mayoría de inconvenientes que tengas. Recomendadisimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'fb52990b4251ecf5b77e2cb21094fa7faa125f544c059341e18a5b5c18a56ff3'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Las tareas que deja son sencillitas aunque un toque largas, pero no duran mas de un dia en eso. El trabajo de investigacion lo agarra a uno desprevenido porque empieza desde las primeras semanas. 3 examenes faciles'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Pocos exámenes']::TEXT[], '2025-01-03T00:00:00+00:00'::TIMESTAMPTZ, '3f122b30efbf686f63abcce215acf6d1fa5869ee1ae3297cc335da9cced15eb0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El compa es una teja, si encuentra campo con él no lo dude, él es super chill y pasar con 9 es un queque, es muy interesante el curso. Las evaluaciones son super fácil y hay un proyecto grupal. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Da crédito extra']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, '6fb7369a5473403ce5c275de4de9113216224231904955607d703b0f1f86b82a'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El mejor profesor de la escuela de ciencias sociales. Abarca el curso desde la reflexión sobre la violencia, la evaluación es 40% 2 ensayos (uno grupal y otro individual), 30% Tareas-Trabajos en clases súper sencillos y 30% en una investigación que debe de fomentarla en el eje del curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '8a196a67a1ed19dbc98e869998cc4b19afc36e349a6fb55e49be518cb86fa3a7'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'El curso se pasa solo, pero llevarlo con él fue super nice, los trabajos no eran pesados y la mayorías de cosas se podían hacer en parejas. Aparte es ese tipo de personas que motivan al estudiante, definitivamente llevaría con él más cursos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f6e2f43d71c6f9371dc7addcfa7e1c8ec257dd9700e30bee88238450a022301f'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Evaluaciones sencillas, la clase no resulta pesada; si puede matricular con él: no lo dude.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'da85284bd86b340a725d101f630adc1dcf76fb786f933ae0c82fc79da41684be'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Muy buen profesor, hace las clases divertidas y pone evaluaciones diferentes a lo usual, como ver películas o videos por ejemplo. Eso sí, hay que hacer presentaciones en grupo muchas veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, '8fcf999c0f99aadfc0a280df044ca3de448dc8d4c57b4c7b244fd00cdbabf5f4'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor, si tienen la oportunidad de matricular con el, haganle de una!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'f2ba2ee6367ec89e858b3d9fc4f1a06891ae52bd7c12b9f4c972098f2a3a424c'::TEXT, ARRAY[99]::BIGINT[]),
    (116::BIGINT, 'De lo mejor del TEC, si tiene la oportunidad de matrícular con el, dele'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd38d5c053e202a7bf3320c82737cb8598ae31811555418cc5ee1e9a6b2fb4f0a'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es el mejor profe que puede existir, hace el curso que deberia ser aburrido y de relleno entretenido y llevardero . Lo mejor !'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-04-03T00:00:00+00:00'::TIMESTAMPTZ, 'fe6d76be9756c21be4762618ff2443fb5e23a087abba48743a85d65cb767776f'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es el mejor peofe que he tenido en el tec'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '8e8ce69fa4c1dd8be988deb30f9b6a86fb2a5054e9d730ea689cd79b9a1a7e54'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profe y una excelente persona, es la segunda vez que llevo un curso con él y estoy igual de satisfecho, pocas tareas y muy cortitas, hasta la investigación es relativamente fácil. Lo único que podría decir negativo es que las notas las da casi que hasta final del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'e649cffc8fd3e7f9cfbd956eb8c8b3a3796d908bb6cdb57babb37f9bb561f497'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profesor y persona. Es empático, relejado y cómico. Hace que los temas, que podrían no ser tan atractivos, sean interesantes y accesibles. Las evaluaciones (pocas tareas, dos exámenes bonitos) son suaves y sencillas. Maravilloso profesor, llevaría otro curso con él sin dudarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'cbf52b1d26b88397ac0ca43fb6d0d239a6d2cc7b7fb4f32e1ea070363a94bc34'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El mejor profesor del tec, las clases se pasan bien, se aprende y no hace los cursos más pesados de lo que deben ser. De verdad ni lo dude si puede matricular con el, 10/10. Excelente persona y profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '54c26a04be1391ae71524addf71265a46126e996c2875970f27ccba172ca86bf'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'No dude 2 veces en llevar cualquier curso con él. Uno de los mejores profesores y personas que tiene el TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-20T00:00:00+00:00'::TIMESTAMPTZ, '8deffef8b5e49eed9b1dffa795fe624530a81487c0c44d0a523f06da668bb2cf'::TEXT, ARRAY[1004, 628]::BIGINT[]),
    (116::BIGINT, 'Las clases pueden ser un poco aburridas, pero es importante participar. Todos los trabajos y exámenes pueden hacerse en grupo. Pasar no es tan complicado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2022-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'fe220d6b9c1b99ee762a9861dc4fa187f999e7d7ad460e760e91754c438af68f'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Osquitar es un amor, simplemente un profesor tremendamente comprensivo, llevadero, responsable y amable. Lo tkm a Óscar, él fue de los pocos profesores que comprendió una situación personal por la que pasé y me dio su apoyo. Recomendado es poco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4bae1765305593f63950ea88481a48b67b0468343180a82b7fc845fa5fe8510d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Gran profesor, dedicado a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '869459ec1dea0460a149accbda1473d1de4d578e56d614178cfcb9e306b1c7fc'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Clases largas y un poco aburridas si la psicología laboral no es de su interés, pero es un profesor muy agradable y siempre dispuesto a ayudar, sus trabajos toman tiempo pero son fáciles y no califica duro. En los avances siempre da retroalimentación para que el informe final quede bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'eeb480bc90fae1559931233a995025fd002de11cfb6b6ed8e39100acc5ce7256'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Un profesor de calidad!! Sabe mucho de la materia, y las clases son súper interesantes y dinámicas. Se fomenta el trabajo en equipo. Siempre está pendiente a dudas, y las contesta de la mejor manera. Tiene un corazón de oro. Lo recomiendo 100%. De los mejores profes que he tenido!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1d4bee1466b41f98e455798e87eda542fe4519791c0833af0ab64ee1e945e0b8'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'EL profe fomenta mucho los trabajos grupales, con un buen grupo, el curso se pasa bastante bien. Califica suave. No revisa los trabajos hasta el final del semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '583cda3ce9f9a9085f18881d337bb600724661eba009582f86e9173730d5861f'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'El profe es súper buena gente, comprende y respeta mucho a los estudiantes. Además, explica muy bien los temas. En cuanto al curso, las primeras clases debe participar en clase, luego son más trabajos escritos(no pesados) y se trabaja en grupos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'e3b0d054ad1025fcd5d18a478223c068022a83c60c56e36e02a77fec22977ffd'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Súper buena nota, en serio de los mejores profes. Es muy comprensible, hace que la clase no sea tan pesada. Fomenta mucho el trabajo en equipo, con un buen grupo ya la hizo toda. Califica muy chill, excelente profe en serio. Full matriculen el curso con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Pocos exámenes']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '98518bbcdad159bd66528252e425ae43d73408594e9fa9c12b6f810420d70628'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es demasiado buena persona, como la persona más amable que va a conocer. Las clases son normales y llevaderas, los trabajos son bastante fáciles, consigase un grupo para hacer los trabajos, es realmente útil, él fomenta el trabajo en equipo. Casi que inmejorable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-20T00:00:00+00:00'::TIMESTAMPTZ, '07b22ffe28616d5c24059ff1382610e04108be848041c554a7fcc63feb8d01c4'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Los trabajos que deja son muy fáciles, el profe tiene mucha paciencia y explica bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, '48842ed151959b2e4ca22993fa32846ae1218be32978529872dced8ff1dbb5b3'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, muy organizado y sus clases siempre son muy interactivas. Sus evaluaciones son sencillas al igual que los proyectos. Es uno de los mejores profes que puede tener en toda su carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'fc80caab344a902f1331db1b79bc02926e42ddac3ccf40bf728e53f12eb9ff53'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'El mejor profe con el que usted puede llevar la materia que sea. Bastante organizado, buena gente, evaluaciones sencillas. Es el mejor profe que seguro vaya a tener en toda su carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c127a28a7c40865ac82043e0ec883c2153d450c56c40925da38ec6ad555f65fb'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profe y ser humano, las clases son algo largas pero las hace llevaderas y deja salir antes algunas veces, brinda muchísimo apoyo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '6257274cd962487a84edf2ee94972ac0d0f93003420dbef0cfef4743dfa8dba8'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Muy buena persona, a veces me aburrian sus clases, a veces hacía evaluaciones dentro de la clase por lo que sí era necesario conectarse siempre. Los trabajos no eran muy largos ni difíciles y cualquier duda él es súper servicial y ayuda muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'cea761c15b6f99bc773456c6e3c24e246d6f900a7f085622db0a647cf55fb513'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Se pasa muy fácil, explica muy bien los conceptos entonces se aprende mucho sin ser aburrido. Los trabajos y los examenes son muy fáciles y califica suave. Siempre está dispuesto a ayudar al estudiante de cualquier forma, hasta psicológica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '52b72a2367a0482a58ba2d646be83c3d0976565025af2bc0c61949b183c32434'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Virtual. El profesor hace su clase muy sencilla y los conceptos los explica muy claramente y con ejemplos, se aprende mucho de el factor humano y social en las empresas . El material que se utiliza es un poco antiguo algunas veces. El curso con él es muy facil y lo recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'adec6ccb492d965cc292053cdd3559879dad806d7232ee9f7063300ae14d3f5d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El profesor tiene el curso muy bien organizado, es una excelente persona y súper comprensivo. En el curso se aprende bastante del valor del ser humano en una empresa y las relaciones personales. Mejor profe que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-11-09T00:00:00+00:00'::TIMESTAMPTZ, '0c097e24ab44fcd43cc42ec972a3f32bf644f32e8af8153696c268b732dc8555'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El profe es bastante bueno, se preocupa por los estudiantes. Durante todo el semestre se hace un trabajo de investigación, pero es muy fácil. Además, el profe responde las consultas bastante rápido, probablemente ha sido mi profesor favorito en mi recorrido por el TEC. No dude matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-10-25T00:00:00+00:00'::TIMESTAMPTZ, '3ff5fc1f701b64900ec633bde506187f41e3d3508f5fbb00694531fb4ea58483'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Super bueno profe, las clases muy entretenidas pero tampoco exigen la concentración total así que también se puede adelantar cosas a veces, sin embargo vale la pena prestar atención. Super comprensivo y abierto a ideas y ayudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '4cfadf156b7257fa63048b6d34220b40025d1d33f460dea59c6ae727e955ff65'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'De los mejores profesores de la escuela, es super considerado con el estudiante, siempre esta atento del tiempo que consume el curso, excelente manera de enseñar y la clase se vuelve interesante y participativa. Un proyecto grupal que se empieza desde el inicio del semestre, deja unas pocas tareas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '99837dbd33926fbc3581d6e175067d4551e1e32d1022ac91e53d8496062b65df'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Super buena personas, clases claras e interesantes, califica suave y sin dejar muchos trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'bc2585ecb4668705d80ca613852eedee068390065c5d462ad33a3668b1104615'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Un amor, lo recomiendo full.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'd7b4921eedce2441d14d6e2d4aa089988e808551e1df5969915d977b45b92880'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un profe muy bueno, las clases son muy entretenidas y los trabajos son muy fáciles de hacer. Revisa suave, pero sí tiene que tener sentido lo que ponen. Full recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3ce050da0555544fadfc9f1750914bc8a9a31964b4a25efa17fd4ae1dbecc25d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Súper buen docente. Muy comprensivo. Tal vez son clases un poco aburridas pero trata temas muy interesantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'f0a9e6665c391d64232ee48b2254f21c78de75f0117fc04e2b231dfc09d613aa'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El profesor es muy bueno, atento y comprensivo, califica muy fácil y los exámenes los deja para hacerlos en una semana. Claramente tomen sus clases con el no se van a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0d9268379258db21fa1bfc1f92501c21428bf2879b4ffda35db1983479ccefec'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es una gran persona. Muy respetuoso y muy considerando, sus evaluaciones son muy simples pero a la vez hacen recordar puntos importantes. Lo recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '2bb10c5fbf8d24c9313b9282abc70cf969136325887c0995b07cab68f1e24c5f'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un profe muy claro, muy amable y respetuoso, comprensivo con los estudiantes y la situación actual; los trabajos son un poco largos pero no deja muchos, el trabajo final lo asigna desde la primera clase y se entrega hasta la última semana 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, '18cc6b7df657d0ea845f17ef03388e9e156bd1464dde22893f028ef32d9b4417'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Deja muchas tareas, sin embargo son sencillas y cortas en su mayoría, además de que califica muy suave. Hay un proyecto muy largo y en grupo, pero lo deja desde inicios de semestre por lo que tampoco representa mayor problema y nada más hay que cuidarse de seguir las normas APA.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'e1f0f0929c9417d6336a3d95f2c346b1142bb24541d753d140c21dea304c4ffc'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Un profe super agradable y muy comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '7c0bf6ed8f46a34da94bd013a2f7cfb351224d0d4f961133a85a2d4748b964c0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, las clases son entretenidas y no son muy largas. Muy amable, servicial, siempre atento a responder dudas con toda la disposición del mundo, muy amigable, inspira confianza.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '323b9f2cda28c0d1779031c3d228e03df252e9839ba644010fe2cc38c65b27b3'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'fa01697dd1d22042375f925d22d8006e5ce82e05ebf33bf47eb6497efe7b2891'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Le importan los estudiantes, deja bastantes tareas cortas y fáciles de hacer. Se puede contactar en cualquier momento, y siempre ayuda si el estudiante tiene algún problema. La materia en general es aburrida, pero las clases son interesantes, a veces hay que ver películas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2020-12-24T00:00:00+00:00'::TIMESTAMPTZ, 'e3c311733f5ece81aaf5d12205b769e19f31313480d030f256d1cc5bea7a81be'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, le gusta q la gente participe, le encanta q la gente se anime a discutir temas interesantes, q presenten temas del interés del estudiante (reflexiones, videos informativos...). Deja tareas pero se hacen en 2 toques, recomendadísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'd2d750c7524447104453bbfd60e54da3a59a6eec7a06a7999a148fc4a0a22363'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'aab471d9f96a26b8b1cb500f7c8145c32d654ce6b2cf953febad2a6526925ac9'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Matricule con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '9a3fc5cf5d8dc5c58b09a40553e518d7342f10463d0a24b36496030312f84fcc'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Se adaptó muy bien a las clases virtuales y de verdad le importa que nos vaya bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '57170ff90d540ada4fc772fbe6b6eed36f740973dbe69330a29d058a271f0507'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'El curso es fácil y el lo hace súper ameno! Se adaptó súper bien a la modalidad virtual. Deja trabajos (casi) todas las semanas pero rápidos, fáciles y en grupos (los exámenes igual). Matricule con él sin miedo!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'f1163d61b1b562e61c81cae9400ba80b054dc1469324f81d1f2ccd5f2cc9d2fd'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'd54e2453f348c2cf74242a3eac58787ce9dc9e2f676ab3d3e6d6f21e56efe0a8'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El mejor profe, entiende que hay cursos más pesados y hace el curso suave para dedicarle más a los demás. Excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '845d34913d7afb57e07827f4af27bc81c4632682daf005a87d917357e1d96160'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Si tiene dudas se las responde con claridad. Si pone atención las clases son muy interesantes. Uno puede aprender mucho con él. Responde dudas casi que inmediatamente. A uno le puede ir muy bien si le pone en los trabajos, no son complicados pero sí pueden tomar su tiempillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '2e03b068a8a9c590a4869e57c7e89278982cae62029d5f2c5fc91158fce981c0'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es súper buena gente, siempre atiende dudas rápido y deja todos los aspectos súper claros y hace las clases interesantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'fc5e98610edffe32b224be497105e2095fc3521782f9767352c3add027425b81'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'El profe es bueno y se preocupa por que el cursos no sea muy pesado. Las evaluaciones son fáciles, intenta que las clases no sean aburridas y explica todo lo necesario en el curso. Es muy buena persona y ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'f91e07a9fd1032a7bc6b1ac6fbdd14b9727aaa5ae94452e4d8cb20b8b39e0b5c'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profesor, además de gran persona. Ojalá todos los profes fueran como él, es claro a la hora de explicar y le saca mucho el jugo a cualquier tema y como se ve reflejado en la vida real. Su trato hacia los alumnos es incomparable, recomendado, un 10/10 en todo sentido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '536819431e36c9d80a357adadad5c0e23319f8ab7484f6c7bf990fc886a4876d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Pocos trabajos y muy sencillos, da bastante tiempo para entregarlos y se pueden hacer en grupo. Las clases son largas y aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '33c4571e219d23c9680a9e95eef2be8eb35c35fd757c951262a3cca0e8d8d4f0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profe, se preocupa mucho por el bienestar del estudiante. En modalidad virtual, el profe es muy comprensivo, hace el curso cero demandante. Pone trabajos bastante cortos, que podés hacer en grupos. Para los exámenes tenés una semana y son muy sencillos. El proyecto es investigación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'c3b9addee85f709c3a5dd3068462dfc8de1995c5b82cf6421f4fed43b31528cb'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-05-17T00:00:00+00:00'::TIMESTAMPTZ, '438ac54ac44b367f7ec304a132fcea90dce049dded52f9cdbb1d03496d6fefeb'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'excelente profe, sabe que la materia se puede volver aburrida pero la hace interesante, se aprende bastante y deja muchas enseñanza, muy fácil de pasar con buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '30c062d1ee935c64ffc3b118532197bd6f6e30dda0e59d9fbcf388b2cd6a1bef'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '7d596e6bd2349645940e699dac3f235bc05350a3486ab73cd17adc3604cf635e'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'El profe mas buena nota para cursos de ciencias sociales, es cero aburrido y hace que uno quiera participar y debatir siempre. El curso no es nada pesado y el entiende que uno lleva otros cursos por lo que deja salir temprano. Ah y si parece Jesús en todo sentido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-29T00:00:00+00:00'::TIMESTAMPTZ, 'b15bc9bfe809b4626c666105a6184998bd8a1684f2b60d900a7d6ba9df5c649d'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Rey de reyes,señor de señores,sabiduría personificada,macho alfa,lomo plateado,barba de leñador,voz de espartano,biceps de goku, pectorales de acero,verga de oro,domador de dragones,cazador de mamuts,guardian de la tierra,héroe de leyenda,hombre perfecto, salvador del universo,unificador de naciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, '8d150f51089bed043aafeaf850878847b82726e30b23ae31ff924e424e0d2bd8'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Calidad de profe, demasiado pura vida y hace que el curso no sea tan aburrido. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1ebef0cd2c316845755e0070a7c620dd7d7957a06e9058cd7deebab3e1c6917e'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, las clases son muy amenas. La materia puede ser monótona pero él la hace interesante con un ejemplo para todo lo que explica por sus años de experiencia. Los exámenes se basan en el contenido de las presentaciones y él dice qué es lo importante de saber.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7ba114810d979392466ffe6e5eb1123c9d4ead3cfdb6408dc41427756c6e04dd'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El un profesor muy respetuoso y amigable que hace la clase muy entretenida. Los trabajos son sencillos y el proyecto también. Con él el curso no es pesado y nadie se queda porque todo queda muy claro. Es la mejor opción para tomar una clase de seminario. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '3056fea911028e6064686320960f3c2dcf4100fb467deb835f49b9eb78c562a2'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Un profesor excelente pero cuesta mucho prestar atención debido a sus pectorales fornidos y figura de Aquiles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'be07572d5ffe9dd6adbc27c10d9f37eb6a0b9b7bfadf7bd6adfbac8bfd81b616'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Muy buen profe. Da mucho apoyo y motivación a los estudiantes. A veces las clases pueden resultar aburridas, pero generalmente hace el curso muy llevadero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2019-11-10T00:00:00+00:00'::TIMESTAMPTZ, '0643e6b2c3d0bd1c527bd1f073815be3909700b1d40031d7bc6ac9f68a41277e'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Super entretenida la clase, curso sencillo con solo hacer bien los trabajos se pasa con excelente nota. Profe buena gente. En intro hay un poco más de evaluaciones, pero algunas hsta son en parejas. Seminario tienen menos. La cantidad adecuada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4c45ec8aa0c83d8c35773fd08b6a5a50bd77c5785eab37516118fa66f4958da5'::TEXT, ARRAY[559, 1004]::BIGINT[]),
    (116::BIGINT, 'Muy buen profe, no tengo ninguna queja a cerca de él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e3fcb836f4c0f23617b37fbc60201db5caa2388e5c5df83ef4b95096485a0dd3'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b95aad549e8c30cc3d8fa3c3ce1264b53e8b4b3a9f9b2526a0cde20071ca4c33'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ae94cdc14142274ad2497511349d431d8846cfc358670d02af0af6cb72df9418'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Se pasa sola con él. Es un saico que califica super suave. Meta lo que sea con él, es muy pichudo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3d46f0d1350b875e584a4e1bbb0bb5dc7c3b242430405b764eef59d50e814730'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor, hace el curso muy ligero, realmente lo inspira a uno y es super vacilón, de los mejores profes que he tenido y de los mejores de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '43f2c31625e5ff30cb5851ed36000bcb5e78ebc804df6859f5c7ecb2c6116b6a'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Buen profe, intenta hacer las clases lo menos aburridas posibles, y los trabajos son muy sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '086ca482004c9d5ec0bc6d21b0cbe74b2d2bf3ae37b75a3e20f89a96dd1c9e1c'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Su clase es muy amena e interesante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, '9d9cd57a09b6cc8b3a7e9e78c92b411f449d1d81c6ed6a8e8a619b57b86d5cf3'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Hace 2000 años le decían el Mesías, pescador de hombres, el sentado a la derecha del padre, 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'af3e35fcf33ec15a6ebca4d484f5ca7ce39d0f42a3a22532db0a2b43e44f181f'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es básicamente la mentalidad de Gandhi con el cuerpo de Jason Momoa. Un dios de dioses.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'e82d3bcdc8089ac84ae71056539f0985c5cf0b9c158669df5fdce795febaffc3'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profesor, deja todo claro y la mayor parte de trabajos se hacen en clase, él evita saturar de tareas para el hogar al estudiante. Calidad de persona y profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'c062f976fc26c7f8dc7dddc04b6c874e5a6691fe015dfb781597be655ab2a82d'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Excelente ser humano, muy profesional y considerado a la hora de dejar tareas. Casi todos los trabajos se hacen en clase propiamente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-04-17T00:00:00+00:00'::TIMESTAMPTZ, 'cd87481982cd9efd0fecc5dbccfadf55e0dd48e898b6fb4d5e09506f2d1f2963'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0b63f036032dc131aeb5b4b592492d289c332c1515c6051139654955e55e8883'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'El mejor profesor sin duda, Hombre Cazador Recolector es un dios de la enseñanza y recomiendo matricular con él ya sea que busque salir adelante con la carrera o salir de la depresión, este Señor es el Protector de la Tierra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-19T00:00:00+00:00'::TIMESTAMPTZ, '303d6b3ae0b682657fb0ed577834da94d32df8bcdaa78359bace3ff3f0474111'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Super recomendado. Es muy organizado para planear la clase, programa todo para que el curso no sea para nada aburrido, muy respetuoso y contagia de buena energía a las personas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0452d9f15bb8a8fd0fe5c334a2e9d20cea24567566eac3276f30b4341da674e6'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es un excelente profesor, se nota que ama lo que hace y es muy comprensivo con los estudiantes. Matricule con él y tendrá un 100 sin duda en el curso, pocas evaluaciones y muy fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a0b6c339903f26cb609aaa2ba1a388ac5f2d7345ddd0f290aecd6e2fb33e1858'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Basicamente es ir a clases, hacer las tareas y se pasa con 100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'cedcf4b50ec7b97f8bea974178b05c7940527dea643b9dabee31c4608bc7cb8b'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, hace muy entretenidas las clases, muy flexible con los ensayos y tiempos de entrega de los trabajos, muy buena persona, trasmite demasiada energía y buenas vibras. Todos los cursos que puedan llevar con el llevénlos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'b7df4588b998c094b7f80c5d30be0159af99c93f0144be235b4f50a94b81d620'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Excelente! El curso es aburrido pero el profe intenta hacerlo entretenido. Se pasa un buen rato. Trabajos fáciles; comentar videos en clase, un par de ensayos que se pueden negociar, comentarios de películas y el trabajo de investigación. Se pasa fácil si se entrega todo y es flexible con las fechas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '9d4347a33144877ed0f27fbb2a5e5eab6cee3926a7d94b9bdbfbee0ed4b998ec'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Es de lejos el mejor profesor de la escuela de ciencias sociales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '2cfcbbefa3dcc751d5c46764e8e836cddf9f67c7097b1aed7dbc893954397d90'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e26c890d1ebbaecb98432da4d76ade4d945a3babb2fd89f1b29f3ac76d9c64a3'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Lo recomiendo!! Súper amable, hace la clase muy amena y entretenida. En sí, la materia es aburrida pero se nota que es un excelente profesor y ama lo que hace. Definitivamente si pueden, matriculen con él. Los trabajos son súper fáciles y no son largos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'fc00209e53b4b75d1d0dadc503d06f8595fb781da4e96f90167077ef4a6db017'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'EL MEJOR. Matricule con él. Hace el curso fácil y entretenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '86917b2d5520f2d8f16c1282dbfc5e0bb462bd201e6966b26c81eb404de4129c'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Super recomendado. Deja dos informes de 15 páginas, comentarios de varias películas que se ven y hay un trabajo final que es en grupos. El curso es aburrido en sí, pero el lo hace un poco mas llevadero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '31a67ed590947b50bc7cdef2948dd4d322acdb1562965d0b01745934c05ce900'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Excelente profe y se nota lo mucho que ama lo que hace. Lo que se debe mejorar es el curso como tal pero el profe es el mejor que he tenido en el TEC. Es súper pura vida y sabe un montón. Hace las clases interesantes y explica excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '03c0879b072a92e7c0484bdf6848b91ecff32d614463564dea9d54d477f3d8dd'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Super tuanis y siempre vacila. No deja bretes largos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '83caf0adb60804e7b80af53e2e037c9f508f5ccdba6939a45056be05b454d1e1'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es un profe muy cordial y claro al dar la clase. No diría que es entretenido pero siento que es por la materia. Las tareas son en extremo sencillas, normalmente se hacen en grupo, y no hace quices.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'fe7182ea1a66b0fe23e7f7089dd938786644648f9fe336c0f261737119570430'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'simplemente inspirador, convierte un tema increíblemente aburrido en algo interesante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-02T00:00:00+00:00'::TIMESTAMPTZ, 'dd10c6f75e5520672d491dd87268f2c635e16685ffe2ddb3213bd69d6e08f765'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'El mejor profe de la vida, se nota lo mucho que ama lo que hace. Él logra que el curso no sea una carga, lo exámenes son sencillos, da buena realimentación, clases entretenidas. Nunca había tenido tantas ganas de participar en una clase. El 100 más fácil que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '94929aa885ec038ef115586f05064ca8b6642f9fddd50cfe575978adfa9e5848'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Un profe muy pura vida, todo super claro, clases entretenidas y muy trata de ayudarlo en lo que pueda si tiene algún problema.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '88ff75a3103a1ee837ca77c78aeb92a8d8b981396ef2440e9eb7ad8b9d896ccb'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Uno sale re-preparado para los exámenes y las tareas que manda se hacen en 10 minutos. Solo manda un trabajo grande pero es en grupos. A veces hace exámenes a resumen abierto o en parejas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'd48acc953ef88f142664f2b267c3f3c5a6b0682b3c23a3384a04cf429325c8a1'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'EL MEJOR PROFE DE LA VIDA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '42eac7f71af8c7613d0cf2c38fd84f46754e0371cfca83ef5872d6079e3c9296'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Un profesor con un 100% de vocación, de verdad se nota que ama lo que hace. Increíblemente comprensivo con los estudiantes. Explica clarísimo y se aprende mucho! las evaluaciones que deja son super faciles y aun más si uno pone atención en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd8e814c89766b84fb478a6c1c5280ede111067b57ad51e6b6ff8a344364c791b'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe, hace que la clase sea interesante con sus explicaciones, deja muy pocos trabajos. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7b73f9ae84d961edc5b8fc8b43f8bc643053b24851873b5fd184d0a1ae67557c'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Es un profesor que inspira e incorpora al estudiante en la clase, verdaderamente son de los que valen la pena, ojala hubieran mas así.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd0bb7e2daccd7d9653b07c8979c9ba1e4272bb883fbcbbcee823269ff974a15f'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Hace el curso demasiado relajado, deja muy pocos trabajos y casi con 3 semanas de tiempo de entrega. Curso matriculado con él, curso pasado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0161ec9ef55bbc2d300735caf4300d6b9042dc9b755d0cd764c788cf1b1ccd6a'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Demasiado pura vida. El proyecto es super relajado y los exámenes son super sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '56a948cb2b3d8b39c99385db914bc9dbed2586a431228a74a3e251b1f7fff0d0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Es el mejor!!! Perder una clase con él, duele. Hace la clase interesante (un poco difícil con este curso) y va al grano. Se dividen las lecturas en grupos y cada grupo expone una y da un resumen, así no hay que leérselas todas, es genial!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9ffe95bb5927eac1631192fd4a01f9bacad5d7b437575ef71841a57373f5e0b2'::TEXT, ARRAY[559]::BIGINT[]),
