    (116::BIGINT, 'Excelente profe, siempre con una actitud positiva, motivador.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '18ccb523dec791e7dc3e677741d4298353cdff3478cc77c514eb0f5d3b7440c3'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profe. Se preocupa por el entendimiento de la materia además, es muy amable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-10T00:00:00+00:00'::TIMESTAMPTZ, '92905421c1f193fd1eaf4d0ba7e26375152900edf884158333cf55606183a043'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Excelente profesor, el curso se pasa muy facil y casi todo es en grupo. Tampoco es un relajo pero el profesor hace que el curso valga 2 creditos. Muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '7901b60c89291916fe54be3db6f624862eecd1f1f63951b038499c15e3c8a2c0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Las clases son muy entretenidas, él hace que se disfrute la clase con temas que lo dormiría a uno con cualquier otro profesor. Una teja de profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '6a99055ce58d89fdf5a2d14c31d6bae8e8131c1ea11c435f54f9f13f96597354'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Muy buen profe, no califica muy duro y sus clases claras y trata de hacer que uno pase un buen rato. No deja mucho trabajo y casi que con ir a las clases se pueden hacer fácilmente todos los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '7991baf2aac33f6bc17d681d25a84940e5dda0dd8bc9ac61f96475398bf678d3'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Es muy amable, esta dispuesto a ayudar, busca que el estudiante aprenda, califica bastante suave y aunque la clase puede ser algo pesada, es un crack de profe, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'af8280c77d4b8519f2d96139c0418bdfcc656f26ff6e4ae4ba8f0382bc2c0bf0'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-03-12T00:00:00+00:00'::TIMESTAMPTZ, '707f5e44af15b35b53a4d1dd869ad4800841dcf435ff80866fd2c8eb06fbcec9'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Muy simpático y amable, buen profesor... califica bien y los trabajos son sencillos... y es guapo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '07fec524cec407c9b6a3cd98ad017801490a685007d8251030cfa5961881016d'::TEXT, ARRAY[628]::BIGINT[]),
    (116::BIGINT, 'Super bueno como persona, hace la clase muy entretenida y se aprende bastante.Los trabajos son fáciles y no hay que leer mucho. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'da2ffcdadae6c32913f212a526344a8a44a6401bb67b6a5b70a14ea4cac7d9fd'::TEXT, ARRAY[1004]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '36ba919c2ef630259cc365c485867366952f8132b52ebfeffc978c6ea6fb4918'::TEXT, ARRAY[559]::BIGINT[]),
    (116::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'ad473c02efdb49c26f1c2ba0b1600a9de3344ed1083cffb132321fd0a511ad07'::TEXT, ARRAY[1004]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
